```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[5][5];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            plik >> m[i][j];
    cout << "Glowna przekatna:";
    int s1 = 0;
    for (int i = 0; i < 5; i++) {
        cout << " " << m[i][i];
        s1 += m[i][i];
    }
    cout << endl << "Suma: " << s1 << endl;
    cout << "Przeciwprzekatna:";
    int s2 = 0;
    for (int i = 0; i < 5; i++) {
        cout << " " << m[i][4 - i];
        s2 += m[i][4 - i];
    }
    cout << endl << "Suma: " << s2 << endl;
    return 0;
}
```

Weryfikacja:
- Glowna: m[0][0]=1, m[1][1]=7, m[2][2]=13, m[3][3]=19, m[4][4]=25. Suma=65.
- Przeciw: m[0][4]=5, m[1][3]=9, m[2][2]=13, m[3][1]=17, m[4][0]=21. Suma=65.
